@page "/board"
@using sv_6dd28597cd9c4d94af2ae36e80ace55a.Services
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Project Board</PageTitle>

<h1>Project Board</h1>

@if (isLoading)
{
    <p><em>Loading tasks...</em></p>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar d-flex gap-3 mb-3 p-3 bg-light rounded">
        <span><strong>Total:</strong> @filteredTasks.Count</span>
        <span><strong>To Do:</strong> @GetColumnTasks("To Do").Count</span>
        <span><strong>In Progress:</strong> @GetColumnTasks("In Progress").Count</span>
        <span><strong>Done:</strong> @GetColumnTasks("Done").Count</span>
        <span class="text-danger"><strong>Overdue:</strong> @filteredTasks.Count(t => t.DueDate < DateTime.Today)</span>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchQuery" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row">
        @foreach (var column in columns)
        {
            var columnTasks = GetColumnTasks(column);
            var colIndex = Array.IndexOf(columns, column);
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@column</strong>
                        <span class="badge bg-secondary">@columnTasks.Count</span>
                    </div>
                    <div class="card-body">
                        @foreach (var task in columnTasks)
                        {
                            <div class="card mb-2">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="card-text mb-1 small text-muted">@task.Assignee</p>
                                    <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                    <span class="small ms-2">@task.DueDate.ToString("MMM dd")</span>
                                    <div class="mt-2">
                                        @if (colIndex > 0)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary me-1"
                                                    @onclick="() => MoveTask(task.Id, columns[colIndex - 1])">
                                                &larr; Move Left
                                            </button>
                                        }
                                        @if (colIndex < columns.Length - 1)
                                        {
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    @onclick="() => MoveTask(task.Id, columns[colIndex + 1])">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingToColumn == column)
                        {
                            <div class="card mb-2 border-primary">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Title" @bind="newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-1"
                                           placeholder="Assignee" @bind="newAssignee" />
                                    <select class="form-select form-select-sm mb-1" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-1"
                                           @bind="newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-sm btn-primary" @onclick="SaveNewTask">Save</button>
                                        <button class="btn btn-sm btn-secondary" @onclick="CancelAdd">Cancel</button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary w-100"
                                    @onclick="() => StartAdd(column)">
                                + Add Task
                            </button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private List<TaskItem> filteredTasks => string.IsNullOrWhiteSpace(searchQuery)
        ? allTasks
        : allTasks.Where(t => t.Title.Contains(searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();

    private string searchQuery = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    private string[] columns = { "To Do", "In Progress", "Done" };

    // Add task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
    {
        return filteredTasks.Where(t => t.Status == status).ToList();
    }

    private string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        addingToColumn = null;
    }

    private async Task SaveNewTask()
    {
        if (string.IsNullOrWhiteSpace(newTitle) || addingToColumn is null)
            return;

        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle, newAssignee, newPriority, newDueDate);
            allTasks.Add(created);
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

